// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getValue, getResponseValue, uniqueSuffix } from '@skyramp/skyramp';
import { createLink, pinLink, getLink, getLinkPin, deleteLink } from './skyrampUtils';

// URL for test requests
const URL_localhost = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:3000");

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Definition of authentication header
    const headers: Record<string, string> = {};
    if (process.env.SKYRAMP_TEST_TOKEN && process.env.SKYRAMP_TEST_TOKEN != "") {
        headers["Authorization"] = "Bearer " + process.env.SKYRAMP_TEST_TOKEN;
    }

    const linkUrl = uniqueSuffix("https://example.com/testbot-pin-rejections");

    const linksPostResponse = await createLink(
        client,
        headers,
        linkUrl,
        "testbot-pin-rejections"
    );

    expect(linksPostResponse.statusCode, 'status code').toBe(200);

    expect(getResponseValue(linksPostResponse, "response.name"), 'name').toBe("testbot-pin-rejections");
    expect(getResponseValue(linksPostResponse, "response.url"), 'url').toBe(linkUrl);
    expect(getResponseValue(linksPostResponse, "response.type"), 'type').toBe("url");
    expect(getResponseValue(linksPostResponse, "response.id"), 'id').toBeGreaterThan(0);
    expect(getResponseValue(linksPostResponse, "response.createdById"), 'createdById').toBeGreaterThan(0);

    const linkId = getResponseValue(linksPostResponse, "response.id");
    const ownerId = getResponseValue(linksPostResponse, "response.createdById");

    const linksPinPatchResponse = await pinLink(client, headers, linkId);

    expect(linksPinPatchResponse.statusCode, 'status code').toBe(204);

    expect(getResponseValue(linksPinPatchResponse, "response"), '204 carries no body').toBeNull();

    const links999999999PinPatchResponse = await pinLink(client, headers, 999999999, 400);

    expect(links999999999PinPatchResponse.statusCode, 'status code').toBe(400);

    expect(getResponseValue(links999999999PinPatchResponse, "response.id"), 'refused request returns no link').toBeNull();
    expect(getResponseValue(links999999999PinPatchResponse, "response.pinnedBy"), 'refused request returns no pinnedBy').toBeNull();

    const pinPatchResponse = await pinLink(client, headers, "999999999.5", 400);

    expect(pinPatchResponse.statusCode, 'status code').toBe(400);

    expect(getResponseValue(pinPatchResponse, "response.id"), 'refused request returns no link').toBeNull();
    expect(getResponseValue(pinPatchResponse, "response.pinnedBy"), 'refused request returns no pinnedBy').toBeNull();

    const linksLinksGetResponse = await getLink(client, headers, linkId);

    expect(linksLinksGetResponse.statusCode, 'status code').toBe(200);

    expect(getResponseValue(linksLinksGetResponse, "response.id"), 'id').toBe(linkId);
    expect(getResponseValue(linksLinksGetResponse, "response.name"), 'name').toBe("testbot-pin-rejections");
    expect(getResponseValue(linksLinksGetResponse, "response.pinnedBy").length, 'pinnedBy length').toBe(1);
    expect(getResponseValue(linksLinksGetResponse, "response.pinnedBy.0.id"), 'pinnedBy.0.id').toBe(ownerId);
    expect(getResponseValue(linksLinksGetResponse, "response.pinnedBy.1"), 'pinnedBy.1').toBeNull();

    const linksPinGetResponse = await getLinkPin(client, headers, linkId);

    expect(linksPinGetResponse.statusCode, 'status code').toBe(405);

    expect(getResponseValue(linksPinGetResponse, "response"), 'response').toBe("Method not allowed.");

    const linksLinksDeleteResponse = await deleteLink(client, headers, linkId);

    expect(linksLinksDeleteResponse.statusCode, 'status code').toBe(200);

    expect(getResponseValue(linksLinksDeleteResponse, "response.id"), 'id').toBe(linkId);
});
